package com.gymflow.inventory;import java.time.Instant;import java.util.UUID;public record StockMovementResponse(UUID id,UUID gymId,UUID productId,String productName,MovementType type,int quantity,String reason,Instant createdAt){static StockMovementResponse from(StockMovement m){return new StockMovementResponse(m.getId(),m.getGymId(),m.getProductId(),m.getProductName(),m.getType(),m.getQuantity(),m.getReason(),m.getCreatedAt());}}
